// Bakes data/templates/*.html into lib/templates.ts so the server bundle carries them (no runtime fs reads).
// Each page's <style> holds a /*@base*/ marker that is replaced with the shared data/templates/base.css.
import fs from 'node:fs';
const base = fs.readFileSync('data/templates/base.css', 'utf8').trimEnd();
const bake = (file) => {
  const html = fs.readFileSync(`data/templates/${file}`, 'utf8');
  if (!html.includes('/*@base*/')) throw new Error(`${file} is missing the /*@base*/ style marker`);
  return html.split('/*@base*/').join(base);
};
const out = [
  '// Generated by scripts/build-template.mjs. Edit data/templates/*.html and base.css instead.',
  `export const WELCOME_TEMPLATE = ${JSON.stringify(bake('welcome.html'))};`,
  `export const SOCIAL_TEMPLATE = ${JSON.stringify(bake('social.html'))};`,
  '',
].join('\n');
fs.writeFileSync('lib/templates.ts', out);
console.log('lib/templates.ts written');
